<?php
/** Proof — send and remind (spec "Proof", 6): the outbox rows per invoice contact with the link in the body, never the token in the log; the fake MaluMail is not reached (slice 8 sends); a reminder increments the count; a statement queued the same way. */
require __DIR__ . '/lib.php';
$w = billing_world(); $acme = $w['acme']; $client = $w['client'];
$bea = as_member(28); $marco = as_member(27); $ann = as_member(29);
$betaClient = (int) one('SELECT client_id FROM engagements WHERE id = :e', ['e' => $w['beta']]);
q("INSERT INTO client_contacts (client_id, name, email, receives_invoices) VALUES (:c, 'SMOKE Finance', 'finance@acme.example.invalid', true), (:c, 'SMOKE CTO', 'cto@acme.example.invalid', false)", ['c' => $client]);
$malumailLog = getenv('FAKE_MALUMAIL_LOG') ?: '';
$sentBefore = $malumailLog !== '' && is_file($malumailLog) ? filesize($malumailLog) : 0;

echo "1. An overdue invoice, issued\n";
[$c, $b] = draft($bea, $acme, ['add_unbilled' => 'no', 'issue_date' => '2026-08-01', 'due_date' => '2026-08-31', 'period_end' => '2026-08-31', 'po_number' => 'PO-5']);
$d = (int) $b['record_id'];
act($bea, '/invoices/lines/save.php', ['invoice' => $d, 'kind' => 'fixed', 'description' => 'SMOKE retainer', 'unit_price' => '1000']);
[$c, $b] = act($bea, '/invoices/issue.php', ['invoice' => $d]);
ok($c === 200 && $b['number'] === 'INV-00005' && inv($d)['status'] === 'issued', 'INV-00005 (1,000.00, due 2026-08-31) issued');
[$c, $dd] = screen($bea, '/invoices/' . $d);
ok($c === 200 && $dd['invoice']['overdue'] === true && $dd['invoice']['days_past_due'] === 35, 'it is 35 days overdue');

echo "2. Send\n";
[$c, $b] = act($marco, '/invoices/send.php', ['invoice' => $d]);
ok($c === 403, 'a Manager does not send: 403');
[$c, $b] = act($bea, '/invoices/send.php', ['invoice' => $d, 'to_email' => 'not-an-email']);
ok($c === 422 && str_contains(msg($b), 'not an email address'), 'a bad address: "That is not an email address."');
$since = last_activity_id();
[$c, $b] = act($bea, '/invoices/send.php', ['invoice' => $d, 'message' => 'SMOKE a word from us']);
$rows = outbox('invoice', $d);
$tok = token_in((string) ($rows[0]['body'] ?? ''));
ok($c === 200 && $b['recipients'] === 2 && $b['queued'] === 2 && $b['status'] === 'sent' && inv($d)['status'] === 'sent' && inv($d)['sent_at'] !== null, 'invoice_send: two recipients, two rows queued, the invoice sent');
ok(count($rows) === 2 && array_column($rows, 'to_email') === ['ap@acme.example.invalid', 'finance@acme.example.invalid'] && !in_array('cto@acme.example.invalid', array_column($rows, 'to_email'), true), 'one row per contact who receives invoices (the CTO, who does not, gets none)');
ok($rows[0]['channel'] === 'email' && (int) $rows[0]['client_id'] === $client && $rows[0]['member_id'] === null && $rows[0]['status'] === 'queued' && $rows[0]['record_type'] === 'invoice' && (int) $rows[0]['record_id'] === $d && $rows[0]['kind'] === 'invoice', 'each row: channel email, the client set, queued for the worker, the invoice as its record');
ok($rows[0]['subject'] === 'Invoice INV-00005 — SMOKE Time Acme, August 2026' && str_contains($rows[0]['body'], 'SMOKE a word from us') && str_contains($rows[0]['body'], '1,000.00 USD') && str_contains($rows[0]['body'], 'Aug') , 'the subject "Invoice INV-00005 — SMOKE Time Acme, August 2026"; the body carries the message, the total and the due date');
ok(strlen($tok) === 48 && token_in((string) $rows[1]['body']) === $tok && str_contains((string) $rows[0]['body_html'], '/i/' . $tok), 'the same fresh link (48 hex) in both bodies, in the html too');
ok(!preg_match('/cost|SMOKE Beta|secret/i', (string) $rows[0]['body']), 'the mail names no cost, no other client, no internal note');
ok(visitor('/i/' . $tok)['code'] === 200 && str_contains(visitor('/i/' . $tok)['body'], 'INV-00005'), 'the link in the mail opens the client\'s page');
$log = activity('invoice.send', $since);
$after = json_decode((string) $log[0]['after'], true);
ok(count($log) === 1 && $after['recipients'] === 2 && $after['queued'] === 2 && $after['amount'] === '1000.00' && $after['currency'] === 'USD' && !str_contains(json_encode($log[0]), 'acme.example.invalid') && !str_contains(json_encode($log[0]), $tok) && (int) $log[0]['invoice_id'] === $d, 'invoice.send logged with counts, amount and currency — no address, no token');
ok((int) one("SELECT count(*) FROM activity_log WHERE route ~ '[a-f0-9]{48}'") === 0, 'no row of the log holds a link');
ok($malumailLog === '' || !is_file($malumailLog) || (is_file($malumailLog) && filesize($malumailLog) === $sentBefore), 'nothing reached the fake MaluMail: this slice only queues (slice 8 sends)');
$first = $tok;
[$c, $b] = act($bea, '/invoices/send.php', ['invoice' => $d, 'to_email' => 'Other@X.example.invalid']);
$rows2 = outbox('invoice', $d);
$tok2 = token_in((string) end($rows2)['body']);
ok($c === 200 && $b['recipients'] === 1 && count($rows2) === 3 && end($rows2)['to_email'] === 'other@x.example.invalid' && $tok2 !== $first && visitor('/i/' . $first)['code'] === 404 && visitor('/i/' . $tok2)['code'] === 200, 'an address typed overrides the contacts; a send makes a fresh link and the previous one stops working');
[$c, $b] = draft($bea, $acme, ['add_unbilled' => 'no']);
$dr = (int) $b['record_id'];
[$c, $b] = act($bea, '/invoices/send.php', ['invoice' => $dr]);
ok($c === 422 && msg($b) === 'Issue the invoice before sending it', 'a draft: "Issue the invoice before sending it"');
act($bea, '/invoices/delete.php', ['invoice' => $dr]);
[$c, $b] = act($bea, '/invoices/send.php', ['invoice' => (int) one("SELECT id FROM invoices WHERE number = 'INV-00001'")]);
ok($c === 422 && str_contains(msg($b), 'is paid and is not sent'), 'a paid invoice is not sent');
q('UPDATE client_contacts SET receives_invoices = false WHERE client_id = :c', ['c' => $betaClient]);
q('UPDATE clients SET email = NULL WHERE id = :c', ['c' => $betaClient]);
[$c, $b] = act($bea, '/invoices/send.php', ['invoice' => (int) one("SELECT id FROM invoices WHERE number = 'INV-00004'")]);
ok($c === 422 && str_contains(msg($b), 'Nobody to send it to') , 'a client with no contact who receives invoices and no email: "Nobody to send it to…"');
q("UPDATE clients SET email = 'billing@beta.example.invalid' WHERE id = :c", ['c' => $betaClient]);
[$c, $b] = act($bea, '/invoices/send.php', ['invoice' => (int) one("SELECT id FROM invoices WHERE number = 'INV-00004'")]);
$ob4 = outbox('invoice', (int) one("SELECT id FROM invoices WHERE number = 'INV-00004'"));
ok($c === 200 && end($ob4)['to_email'] === 'billing@beta.example.invalid', 'the client\'s own email is the fallback when no contact receives invoices');
q('UPDATE client_contacts SET receives_invoices = true WHERE client_id = :c', ['c' => $betaClient]);

echo "3. Remind\n";
[$c, $b] = act($marco, '/invoices/remind.php', ['invoice' => $d]);
ok($c === 403, 'a Manager does not remind: 403');
[$c, $b] = act($bea, '/invoices/remind.php', ['invoice' => (int) one("SELECT id FROM invoices WHERE number = 'INV-00004'")]);
ok($c === 422 && str_contains(msg($b), 'is not past due'), 'an invoice not yet due: "…is not past due (due …)"');
[$c, $b] = act($bea, '/invoices/remind.php', ['invoice' => (int) one("SELECT id FROM invoices WHERE number = 'INV-00001'")]);
ok($c === 422 && str_contains(msg($b), 'only an open invoice is reminded'), 'a paid invoice is not reminded');
$since = last_activity_id();
[$c, $b] = act($bea, '/invoices/remind.php', ['invoice' => $d]);
$i = inv($d);
$rem = outbox('reminder', $d);
$tok3 = token_in((string) ($rem[0]['body'] ?? ''));
ok($c === 200 && $b['reminder_count'] === 1 && (int) $i['reminder_count'] === 1 && $i['last_reminder_at'] !== null && count($rem) === 2 && str_starts_with((string) $rem[0]['subject'], 'A reminder: Invoice INV-00005'), 'invoice_remind: reminder_count 1, last_reminder_at stamped, a reminder row per contact');
ok(str_contains((string) $rem[0]['body'], 'gentle reminder') && str_contains((string) $rem[0]['body'], '1,000.00 USD') && strlen($tok3) === 48 && $tok3 !== $tok2 && visitor('/i/' . $tok2)['code'] === 404 && visitor('/i/' . $tok3)['code'] === 200, 'a courtesy in the words ("a gentle reminder"), the balance, a fresh link — the earlier one is dead');
$log = activity('invoice.remind', $since);
$after = json_decode((string) $log[0]['after'], true);
ok(count($log) === 1 && $after['reminder_count'] === 1 && $after['amount'] === '1000.00' && $after['currency'] === 'USD' && $after['recipients'] === 2 && $after['days_past_due'] === 35 && !str_contains(json_encode($log[0]), 'acme.example.invalid') && !str_contains(json_encode($log[0]), $tok3), 'invoice.remind logged: count, the balance, currency, days past due — no address, no token');
[$c, $b] = act($bea, '/invoices/remind.php', ['invoice' => $d, 'message' => 'SMOKE second']);
ok($c === 200 && (int) inv($d)['reminder_count'] === 2 && count(outbox('reminder', $d)) === 4 && str_contains((string) outbox('reminder', $d)[2]['body'], 'SMOKE second'), 'a second reminder: the count is 2, with the message in the body');
$r = page($bea, '/invoices/' . $d);
ok($r['code'] === 200 && str_contains($r['body'], 'Reminded 2 times') && str_contains($r['body'], 'id="invoice-view-remind-btn"') && str_contains($r['body'], 'Send again'), 'the page: "Reminded 2 times", Send a reminder, Send again');

echo "4. The statement, queued the same way\n";
[$c, $b] = act($marco, '/clients/statement-send.php', ['client' => $client]);
ok($c === 403, 'a Manager: 403');
[$c, $b] = act($bea, '/clients/statement-send.php', ['client' => $client, 'from' => date('Y-m-d', time() + 86400)]);
ok($c === 422 && str_contains(msg($b), 'nothing on the statement'), 'an empty period: "There is nothing on the statement for that period."');
$since = last_activity_id();
[$c, $b] = act($bea, '/clients/statement-send.php', ['client' => $client, 'message' => 'SMOKE your statement']);
$rows = outbox('statement');
ok($c === 200 && $b['recipients'] === 2 && count($rows) === 2 && $rows[0]['record_type'] === 'client' && (int) $rows[0]['record_id'] === $client && (int) $rows[0]['client_id'] === $client && str_contains((string) $rows[0]['body'], 'INV-00001') && str_contains((string) $rows[0]['body'], 'SMOKE your statement') && str_contains((string) $rows[0]['body'], 'Balance owed in USD: 1,000.00 USD'), 'statement_send: a row per contact, the lines and the closing balance (1,000.00 USD — INV-00005) in the body');
ok(!str_contains((string) $rows[0]['body'], '/i/'), 'a statement carries no secure link (a link is minted only when an invoice is sent)');
$log = activity('client.statement_send', $since);
$after = json_decode((string) $log[0]['after'], true);
ok(count($log) === 1 && $after['recipients'] === 2 && $after['amount'] === '1000.00' && $after['currency'] === 'USD' && (int) $log[0]['client_id'] === $client && !str_contains(json_encode($log[0]), 'acme.example.invalid'), 'client.statement_send logged: lines, recipients (a count), the closing amount and currency — no address');
q('UPDATE client_contacts SET receives_invoices = false WHERE client_id = :c', ['c' => $betaClient]);
q('UPDATE clients SET email = NULL WHERE id = :c', ['c' => $betaClient]);
[$c, $b] = act($bea, '/clients/statement-send.php', ['client' => $betaClient]);
ok($c === 422 && str_contains(msg($b), 'Nobody to send it to'), 'a client with nobody to send to: refused in words');
q("UPDATE clients SET email = 'billing@beta.example.invalid' WHERE id = :c", ['c' => $betaClient]);
q('UPDATE client_contacts SET receives_invoices = true WHERE client_id = :c', ['c' => $betaClient]);
$r = page($bea, '/clients/' . $client . '/statement');
ok($r['code'] === 200 && str_contains($r['body'], 'id="client-statement-send-btn"'), 'the statement page offers Send to Billing');
finish();
